import { Injectable, Logger } from '@nestjs/common';
import { HttpService } from '@nestjs/axios';
import { AxiosRequestConfig, AxiosResponse } from 'axios';
import { acquireServiceCredential } from '../discovery/service-credential';
import {
  handleAll,
  retry,
  ExponentialBackoff,
  ConstantBackoff,
  wrap,
} from 'cockatiel';

// DEFAULT_TIMEOUT_MS and RETRY_MAX_ATTEMPTS are exported so the generated
// resilience-config spec can assert the values this generator baked in equal
// the values the resilience profile resolved for this dependency. Both are
// load-bearing: the policies below are built from them, never from a
